import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-03-25 :: Ceph Science User Group Meeting","description":"","frontmatter":{"title":"2020-03-25 :: Ceph Science User Group Meeting","date":"2020-03-25T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","BlueStore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","擦除编码","复制","快照","克隆","虚拟化","云计算","存储","监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-25_-_-_Ceph_Science_User_Group_Meeting.md","filePath":"posts/2020/2020-03-25_-_-_Ceph_Science_User_Group_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-03-25_-_-_Ceph_Science_User_Group_Meeting.md"};function o(n,e,s,h,c,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Matthew（Sanger Institute）</li><li>Diamond Light Source的代表</li></ul><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了COVID-19疫情期间的工作状态、Ceph存储系统的最新动态、技术问题和解决方案。</p><h4 id="工作状态更新" tabindex="-1">工作状态更新 <a class="header-anchor" href="#工作状态更新" aria-label="Permalink to &quot;工作状态更新&quot;">​</a></h4><ul><li>大多数人在家工作，只有少数必要人员在现场。</li><li>讨论了在家工作的体验和挑战。</li></ul><h4 id="ceph相关讨论" tabindex="-1">Ceph相关讨论 <a class="header-anchor" href="#ceph相关讨论" aria-label="Permalink to &quot;Ceph相关讨论&quot;">​</a></h4><ul><li><strong>Octopus版本更新</strong>：讨论了新版本Octopus的安装问题，特别是依赖项缺失的问题，以及仓库工作方式的变化。</li><li><strong>容器化部署</strong>：讨论了Ceph部署在容器中的优缺点，多数人倾向于直接在专用硬件上部署。</li><li><strong>自动修复功能</strong>：讨论了Ceph的自动修复功能，如何在发现不一致时立即修复。</li><li><strong>压缩算法问题</strong>：提到了一个关于压缩算法（lz4）的数据损坏问题，建议使用其他压缩算法如snappy。</li><li><strong>文件系统布局</strong>：讨论了CephFS的布局和性能问题，特别是关于使用擦除编码池的建议。</li><li><strong>硬件更新策略</strong>：讨论了硬件过保后的处理策略。</li><li><strong>内存中的OSD</strong>：讨论了在内存中运行OSD的可能性及其性能影响。</li><li><strong>邮件服务器</strong>：讨论了自托管邮件服务器的使用情况。</li></ul><h4 id="其他技术讨论" tabindex="-1">其他技术讨论 <a class="header-anchor" href="#其他技术讨论" aria-label="Permalink to &quot;其他技术讨论&quot;">​</a></h4><ul><li><strong>压缩算法问题</strong>：提到了一个关于压缩算法（lz4）的数据损坏问题，建议使用其他压缩算法如snappy。</li><li><strong>文件系统布局</strong>：讨论了CephFS的布局和性能问题，特别是关于使用擦除编码池的建议。</li><li><strong>硬件更新策略</strong>：讨论了硬件过保后的处理策略。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控和测试Ceph的新版本和功能。</li><li>考虑硬件更新和迁移策略。</li><li>探索和优化邮件服务器解决方案。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>感谢所有参与者的参与，并提醒大家保持安全和健康。</li><li>下一次会议预计在5月底举行，具体信息将提前通知。</li></ul>',15)])])}const d=a(r,[["render",o]]);export{u as __pageData,d as default};
